files.content:
:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --primary: #f0a500;
  --text: #e0e0e0;
  --border: #f0a500;
}

[hidden] { display: none !important; }

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', monospace;
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 8px;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: 0 0 0 4px var(--bg), 0 0 0 8px var(--border);
}

h1 {
  font-size: 24px;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--primary);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

label {
  font-size: 16px;
  color: var(--primary);
}

input, select {
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 4px;
  color: var(--text);
  font-size: 18px;
  padding: 8px 10px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.1s;
}

input:focus, select:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary);
}

button {
  background: var(--primary);
  border: none;
  border-radius: 4px;
  color: var(--bg);
  cursor: pointer;
  font-family: inherit;
  font-size: 20px;
  font-weight: bold;
  padding: 12px;
  text-transform: uppercase;
  letter-spacing: 2px;
  transition: background 0.1s, transform 0.05s;
}

button:hover {
  background: #ffb733;
}

button:focus {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
  background: #d18f00;
}

.result-display {
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 4px;
  padding: 12px;
  text-align: right;
  font-size: 28px;
  min-height: 60px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  color: var(--primary);
  word-break: break-all;
}

@media (max-width: 400px) {
  body { font-size: 16px; }
  .card { padding: 16px; gap: 12px; }
  h1 { font-size: 20px; }
  input, select, button { font-size: 16px; }
  .result-display { font-size: 24px; }
}

const leftInput = document.getElementById('left');
const rightInput = document.getElementById('right');
const operationSelect = document.getElementById('operation');
const calculateBtn = document.getElementById('calculate');
const resultOutput = document.getElementById('result');

function calculate() {
  const leftRaw = leftInput.value.trim();
  const rightRaw = rightInput.value.trim();

  if (leftRaw === '' || rightRaw === '') {
    resultOutput.textContent = 'Error';
    return;
  }

  const left = Number(leftRaw);
  const right = Number(rightRaw);

  if (!Number.isFinite(left) || !Number.isFinite(right)) {
    resultOutput.textContent = 'Error';
    return;
  }

  const operation = operationSelect.value;
  let result;

  switch (operation) {
    case 'add':
      result = left + right;
      break;
    case 'subtract':
      result = left - right;
      break;
    case 'multiply':
      result = left * right;
      break;
    case 'divide':
      if (right === 0) {
        resultOutput.textContent = 'Error';
        return;
      }
      result = left / right;
      break;
    default:
      resultOutput.textContent = 'Error';
      return;
  }

  if (!Number.isFinite(result)) {
    resultOutput.textContent = 'Error';
    return;
  }

  resultOutput.textContent = String(result);
}

calculateBtn.addEventListener('click', calculate);

[leftInput, rightInput, operationSelect].forEach(el => {
  el.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      calculate();
    }
  });
});
